examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchTabs(
        {{groups.0.label}},
        selection: $lineSel,
        items: [
            MonarchTabsItem({{groups.0.tabs.0.label}}, value: {{groups.0.tabs.0.value}}),
            MonarchTabsItem({{groups.0.tabs.1.label}}, value: {{groups.0.tabs.1.value}}),
            MonarchTabsItem({{groups.0.tabs.2.label}}, value: {{groups.0.tabs.2.value}}, isDisabled: {{groups.0.tabs.2.disabled}}),
        ],
        variant: {{groups.0.variant|case}}
    )
    Text([{{groups.0.tabs.0.value}}: {{groups.0.tabs.0.content}}, {{groups.0.tabs.1.value}}: {{groups.0.tabs.1.content}}][lineSel] ?? "")
        .monarchTextStyle(.body)
    MonarchTabs(
        {{groups.1.label}},
        selection: $pillSel,
        items: [
            MonarchTabsItem({{groups.1.tabs.0.label}}, value: {{groups.1.tabs.0.value}}),
            MonarchTabsItem({{groups.1.tabs.1.label}}, value: {{groups.1.tabs.1.value}}),
            MonarchTabsItem({{groups.1.tabs.2.label}}, value: {{groups.1.tabs.2.value}}),
        ],
        variant: {{groups.1.variant|case}}
    )
    Text([{{groups.1.tabs.0.value}}: {{groups.1.tabs.0.content}}, {{groups.1.tabs.1.value}}: {{groups.1.tabs.1.content}}, {{groups.1.tabs.2.value}}: {{groups.1.tabs.2.content}}][pillSel] ?? "")
        .monarchTextStyle(.body)
}
